 void loadCompanies(){String extra=db.getString("custom_companies","");if(extra.trim().length()>0){ArrayList<String> all=new ArrayList<>(Arrays.asList(companies));for(String c:extra.split("\\|\\|")){String n=c.trim();boolean exists=false;for(String q:all)if(q.equalsIgnoreCase(n)){exists=true;break;}if(n.length()>0&&!exists)all.add(n);}companies=all.toArray(new String[0]);}saveCompanies();}
 void saveCompanies(){StringBuilder z=new StringBuilder();for(int i=0;i<companies.length;i++){if(i>0)z.append("|");z.append(companies[i]);}db.edit().putString("catalog_companies",z.toString()).apply();}
 int ensureCompany(String name){name=name.trim().toUpperCase(new Locale("es","AR"));for(int i=0;i<companies.length;i++)if(companies[i].equalsIgnoreCase(name))return i;if(name.length()==0)return 0;String[] n=Arrays.copyOf(companies,companies.length+1);n[n.length-1]=name;companies=n;String ex=db.getString("custom_companies","");boolean inCustom=false;for(String q:ex.split("\\|\\|"))if(q.trim().equalsIgnoreCase(name)){inCustom=true;break;}if(!inCustom)db.edit().putString("custom_companies",ex.length()==0?name:ex+"||"+name).apply();saveCompanies();return n.length-1;}
