 void companyDayTrips(int r,int d){String[] ts=trips(r,d);Calendar dc=monday();dc.add(Calendar.DATE,d);SimpleDateFormat df=new SimpleDateFormat("dd/MM",new Locale("es","AR"));int realizados=0,curso=0,pendientes=0,programados=0,reprogramados=0,cancelados=0;for(String t:ts){if(t.contains("REALIZADO"))realizados++;else if(t.contains("EN CURSO"))curso++;else if(t.contains("PEDIDO PENDIENTE"))pendientes++;else if(t.contains("REPROGRAMADO"))reprogramados++;else if(t.contains("CANCELADO"))cancelados++;else programados++;}String title=companies[r]+" · "+dayLong[d]+" "+df.format(dc.getTime())+" · "+ts.length+" VIAJE"+(ts.length>1?"S":"");String resumen="Programados: "+programados+"   En curso: "+curso+"   Realizados: "+realizados+"\nPendientes: "+pendientes+"   Reprogramados: "+reprogramados+"   Cancelados: "+cancelados+"\nTocá un viaje para abrirlo.";new AlertDialog.Builder(this).setTitle(title).setMessage(resumen).setItems(ts,(a,i)->detail(r,d,i,ts[i])).setPositiveButton("+ AGREGAR OTRO VIAJE",(a,b)->form(companies[r],d)).setNegativeButton("Cerrar",null).show();}
 void companyTrips(int r){ArrayList<String> items=new ArrayList<>();ArrayList<Integer> refs=new ArrayList<>();Calendar m=monday();SimpleDateFormat df=new SimpleDateFormat("dd/MM",new Locale("es","AR"));int rea=0,curso=0,pend=0,prog=0,repro=0,canc=0,sinD=0,sinT=0;for(int d=0;d<7;d++){Calendar dc=(Calendar)m.clone();dc.add(Calendar.DATE,d);String[] aa=trips(r,d);for(int i=0;i<aa.length;i++){String v=aa[i];items.add(dayLong[d]+" "+df.format(dc.getTime())+"\n"+tripSummary(v));refs.add(d*1000+i);if(v.contains("REALIZADO"))rea++;else if(v.contains("EN CURSO"))curso++;else if(v.contains("PEDIDO PENDIENTE"))pend++;else if(v.contains("REPROGRAMADO"))repro++;else if(v.contains("CANCELADO"))canc++;else prog++;if(!v.contains("CANCELADO")){if(assignedFrom(v,drivers).length()==0)sinD++;if(assignedFrom(v,trucks).length()==0)sinT++;}}}if(items.size()==0){new AlertDialog.Builder(this).setTitle(companies[r]).setMessage("Sin viajes esta semana").setPositiveButton("+ AGREGAR VIAJE",(x,y)->chooseCompanyDay(r)).setNegativeButton("Cerrar",null).show();return;}StringBuilder resumen=new StringBuilder();for(int d=0;d<7;d++){int n=trips(r,d).length;if(n>0){Calendar dc=(Calendar)m.clone();dc.add(Calendar.DATE,d);resumen.append(dayLong[d]).append(" ").append(df.format(dc.getTime())).append(" · ").append(n).append(" viaje").append(n>1?"s":"").append("\n");}}resumen.append("\nPROGRAMADOS ").append(prog).append(" · EN CURSO ").append(curso).append(" · REALIZADOS ").append(rea).append("\nPENDIENTES ").append(pend).append(" · REPROGRAMADOS ").append(repro).append(" · CANCELADOS ").append(canc);if(sinD>0||sinT>0)resumen.append("\n\nASIGNACIÓN PENDIENTE · sin chofer ").append(sinD).append(" · sin camión ").append(sinT);new AlertDialog.Builder(this).setTitle(companies[r]+" · "+items.size()+" VIAJE"+(items.size()>1?"S":"")+" ESTA SEMANA").setMessage(resumen.toString()+"\n\nTocá un viaje para abrirlo:").setItems(items.toArray(new String[0]),(x,n)->{int z=refs.get(n),d=z/1000,i=z%1000;detail(r,d,i,trips(r,d)[i]);}).setPositiveButton("+ AGREGAR VIAJE",(x,y)->chooseCompanyDay(r)).setNegativeButton("Cerrar",null).show();}
 void chooseCompanyDay(int r){Calendar m=monday();String[] opts=new String[7];SimpleDateFormat df=new SimpleDateFormat("dd/MM",new Locale("es","AR"));for(int d=0;d<7;d++){Calendar dc=(Calendar)m.clone();dc.add(Calendar.DATE,d);int n=trips(r,d).length;opts[d]=dayLong[d]+" "+df.format(dc.getTime())+(n>0?"  ·  "+n+" viaje"+(n>1?"s":""):"  ·  sin viajes");}new AlertDialog.Builder(this).setTitle(companies[r]+" · elegir día").setItems(opts,(a,d)->form(companies[r],d)).setNegativeButton("Cancelar",null).show();}
 void selectCellTrip(int r,int d){String[] a=trips(r,d);if(a.length==0){form(companies[r],d);return;}if(a.length==1){selectTrip(r,d,0);return;}String[] opts=new String[a.length];for(int i=0;i<a.length;i++){String[] p=a[i].split(" · ");String tm=p.length>0?p[0]:"";String sv=p.length>1?p[1]:"VIAJE";String st=a[i].contains("REALIZADO")?"REALIZADO":a[i].contains("EN CURSO")?"EN CURSO":a[i].contains("REPROGRAMADO")?"REPROGRAMADO":a[i].contains("CANCELADO")?"CANCELADO":a[i].contains("PEDIDO PENDIENTE")?"PENDIENTE":"PROGRAMADO";opts[i]=tm+"  ·  "+sv+"  ·  "+st;}new AlertDialog.Builder(this).setTitle(companies[r]+" · "+dayLong[d]).setItems(opts,(x,idx)->selectTrip(r,d,idx)).setNegativeButton("Cerrar",null).show();}
 void selectTrip(int r,int d,int idx){selectedRow=r;selectedDay=d;selectedIdx=idx;if(detailBody==null)return;String[] a=trips(r,d);if(idx<0||idx>=a.length)return;String v=a[idx];String[] p=v.split(" · ");String time=p.length>0?p[0]:"—";String service=p.length>1?p[1]:"VIAJE";String state=v.contains("REALIZADO")?"REALIZADO":v.contains("EN CURSO")?"EN CURSO":v.contains("REPROGRAMADO")?"REPROGRAMADO":v.contains("CANCELADO")?"CANCELADO":v.contains("PEDIDO PENDIENTE")?"PEDIDO PENDIENTE":"PROGRAMADO";String ev=db.getString(evidenceKey(r,d,idx),"");int photos=ev.length()==0?0:ev.split("\\|\\|",-1).length;detailBody.setText("\nEMPRESA\n"+companies[r]+"\n\nDÍA / HORA\n"+days[d]+"  ·  "+time+"\n\nSERVICIO\n"+service+"\n\nESTADO\n"+state+"\n\nDATOS OPERATIVOS\n"+v+"\n\nFOTOS / EVIDENCIAS\n"+photos+" archivo"+(photos==1?"":"s"));detailBody.setTextColor(stateColor(v));if(detailOpen!=null)detailOpen.setEnabled(true);if(detailState!=null)detailState.setEnabled(true);if(detailEdit!=null)detailEdit.setEnabled(true);if(detailMove!=null)detailMove.setEnabled(true);}
 void dayView(){String[] opts=new String[7];Calendar c=(Calendar)week.clone();for(int d=0;d<7;d++){Calendar z=(Calendar)c.clone();z.add(Calendar.DAY_OF_MONTH,d);opts[d]=dayLong[d]+"  "+new SimpleDateFormat("dd/MM",Locale.getDefault()).format(z.getTime());}new AlertDialog.Builder(this).setTitle("VER DÍA · "+weekTitle.getText()).setItems(opts,(a,d)->showDay(d)).show();}
 void showDay(int d){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(12),dp(8),dp(12),dp(12));int companiesMoved=0,totalTrips=0;for(int r:displayOrder()){String[] aa=trips(r,d);if(aa.length==0)continue;companiesMoved++;totalTrips+=aa.length;int rea=0,curso=0,pend=0,otros=0;for(String v:aa){if(v.contains("REALIZADO"))rea++;else if(v.contains("EN CURSO"))curso++;else if(v.contains("PEDIDO PENDIENTE"))pend++;else otros++;}final int rr=r;TextView card=tx(companies[r]+"  ·  "+aa.length+" VIAJE"+(aa.length>1?"S":"")+"\n✓ "+rea+"  ▶ "+curso+"  • "+pend+" pendientes  ·  "+otros+" otros",13,WHITE);GradientDrawable g=shape(PANEL2,dp(12));g.setStroke(dp(1),GREEN);card.setBackground(g);card.setPadding(dp(14),dp(10),dp(14),dp(10));card.setOnClickListener(v->companyDayTrips(rr,d));box.addView(card,new LinearLayout.LayoutParams(-1,dp(70)));}if(companiesMoved==0)box.addView(tx("No hubo movimiento para este día.",14,MUTED));ScrollView sc=new ScrollView(this);sc.addView(box);Calendar fecha=monday();fecha.add(Calendar.DATE,d);String fechaTxt=new SimpleDateFormat("dd/MM",new Locale("es","AR")).format(fecha.getTime());new AlertDialog.Builder(this).setTitle(dayLong[d]+" "+fechaTxt+" · "+companiesMoved+" EMPRESAS · "+totalTrips+" VIAJES").setView(sc).setPositiveButton("+ NUEVO VIAJE",(x,y)->form("",d)).setNegativeButton("Cerrar",null).show();}
